package com.yessteveskill.paper;
import com.yessteveattribute.paper.PaperAttributeService; import io.lumine.mythic.api.adapters.AbstractEntity; import io.lumine.mythic.api.config.MythicLineConfig; import io.lumine.mythic.api.skills.conditions.IEntityCondition; import org.bukkit.entity.Player;
final class YsaAttributeCondition implements IEntityCondition { private final PaperAttributeService service; private final String attribute,operator; private final double expected; YsaAttributeCondition(MythicLineConfig c,PaperAttributeService s){service=s;attribute=c.getString("attribute","");String v=c.getString("value","0").trim();operator=v.startsWith(">=")||v.startsWith("<=")?v.substring(0,2):v.substring(0,1);expected=Double.parseDouble(v.substring(operator.length()).trim());} @Override public boolean check(AbstractEntity e){if(e==null||!e.isPlayer())return false;double a=service.snapshot((Player)e.getBukkitEntity()).get(attribute);if(operator.equals(">"))return a>expected;if(operator.equals(">="))return a>=expected;if(operator.equals("<"))return a<expected;if(operator.equals("<="))return a<=expected;if(operator.equals("="))return a==expected;return false;}}
